import AppKit
import Foundation
import Testing
import UniformTypeIdentifiers
@testable import ClipDeck

@Suite(.serialized) @MainActor
struct PrivacyAndRestoreFidelityTests {
    // MARK: Privacy

    @Test(arguments: [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword"
    ])
    func markedContentIsSkippedWithoutReadingItsData(marker: String) throws {
        let fixture = try PrivacyFixture()
        defer { fixture.close() }
        let provider = CountingStringProvider(value: "hunter2")
        let secret = NSPasteboardItem()
        secret.setDataProvider(provider, forTypes: [.string])
        secret.setData(Data(), forType: .init(marker))
        fixture.write([secret])

        fixture.store.pollPasteboard()
        fixture.store.pollPasteboard()

        #expect(fixture.store.items.isEmpty)
        #expect(fixture.store.captureWarning == nil)
        #expect(provider.readCount == 0)
        withExtendedLifetime(provider) {}
    }

    @Test func markedContentIsRecordedWhenTheUserTurnsSkippingOff() throws {
        let fixture = try PrivacyFixture()
        defer { fixture.close() }
        fixture.store.privacySettings.skipsMarkedContent = false
        let item = NSPasteboardItem()
        item.setString("not secret after all", forType: .string)
        item.setData(Data(), forType: .init("org.nspasteboard.TransientType"))
        fixture.write([item])

        fixture.store.pollPasteboard()

        #expect(fixture.store.items.first?.text == "not secret after all")
    }

    @Test func declaredSourceApplicationCanBeIgnored() throws {
        let fixture = try PrivacyFixture(frontmost: "com.example.editor")
        defer { fixture.close() }
        fixture.store.privacySettings.ignore(bundleIdentifier: "com.example.vault")
        let item = NSPasteboardItem()
        item.setString("from the vault", forType: .string)
        item.setString("com.example.vault", forType: .init(CapturePrivacyRules.sourceType))
        fixture.write([item])

        fixture.store.pollPasteboard()

        #expect(fixture.store.items.isEmpty)
    }

    @Test func frontmostApplicationIsUsedOnlyWhenTheSourceIsUndeclared() throws {
        let fixture = try PrivacyFixture(frontmost: "com.example.vault")
        defer { fixture.close() }
        fixture.store.privacySettings.ignore(bundleIdentifier: "com.example.vault")

        fixture.write([privacyText("copied while the vault was frontmost")])
        fixture.store.pollPasteboard()
        #expect(fixture.store.items.isEmpty)

        let declared = privacyText("declared by another app")
        declared.setString("com.example.editor", forType: .init(CapturePrivacyRules.sourceType))
        fixture.write([declared])
        fixture.store.pollPasteboard()
        #expect(fixture.store.items.first?.text == "declared by another app")
    }

    @Test func ignoredApplicationsPersistAndExcludeClipDeckItself() throws {
        let suite = "ClipDeckPrivacySettings.\(UUID().uuidString)"
        let defaults = try #require(UserDefaults(suiteName: suite))
        defer { defaults.removePersistentDomain(forName: suite) }

        let settings = CapturePrivacySettings(defaults: defaults)
        #expect(settings.skipsMarkedContent)
        #expect(settings.ignoredBundleIdentifiers == CapturePrivacySettings.defaultIgnoredBundleIdentifiers)
        #expect(settings.usesDefaultIgnoredApplications)

        settings.ignore(bundleIdentifier: " com.example.vault ")
        settings.ignore(bundleIdentifier: "com.example.vault")
        settings.stopIgnoring(bundleIdentifier: "com.apple.keychainaccess")
        settings.skipsMarkedContent = false
        if let ownIdentifier = Bundle.main.bundleIdentifier {
            settings.ignore(bundleIdentifier: ownIdentifier)
            #expect(!settings.ignoredBundleIdentifiers.contains(ownIdentifier))
        }

        let reloaded = CapturePrivacySettings(defaults: defaults)
        #expect(reloaded.ignoredBundleIdentifiers == ["com.apple.Passwords", "com.example.vault"])
        #expect(!reloaded.skipsMarkedContent)
        #expect(!reloaded.usesDefaultIgnoredApplications)

        reloaded.restoreDefaultIgnoredApplications()
        #expect(CapturePrivacySettings(defaults: defaults).usesDefaultIgnoredApplications)
    }

    @Test func privacyRulesPreferMarkersThenDeclaredSourceThenFrontmostApp() {
        var rules = CapturePrivacyRules(ignoredBundleIdentifiers: ["com.example.vault"])
        rules.frontmostBundleIdentifier = "com.example.vault"
        #expect(rules.skipReason(types: ["org.nspasteboard.ConcealedType"], declaredSource: nil)
            == .markedContent("org.nspasteboard.ConcealedType"))
        #expect(rules.skipReason(types: ["public.utf8-plain-text"], declaredSource: nil)
            == .ignoredApplication("com.example.vault"))
        #expect(rules.skipReason(types: ["public.utf8-plain-text"], declaredSource: "com.example.editor") == nil)
        #expect(rules.skipReason(types: ["public.utf8-plain-text"], declaredSource: "  ")
            == .ignoredApplication("com.example.vault"))
        #expect(CapturePrivacyRules.disabled.skipReason(types: ["org.nspasteboard.ConcealedType"], declaredSource: nil) == nil)
    }

    // MARK: Restore fidelity

    @Test func imageWithOnlyHTMLMarkupDoesNotGainAnEmptyPlainText() async throws {
        let fixture = try PrivacyFixture()
        defer { fixture.close() }
        let source = NSPasteboardItem()
        source.setData(try privacyPNG(), forType: .png)
        source.setString(#"<meta charset='utf-8'><img src="https://example.com/cat.png"/>"#, forType: .html)
        fixture.write([source])
        fixture.store.pollPasteboard()
        await fixture.store.waitForPendingImageCapture()
        let item = try #require(fixture.store.items.first)
        #expect(item.image != nil)

        fixture.write([privacyText("something else")])
        #expect(fixture.store.copy(item))

        let restored = try #require(fixture.pasteboard.pasteboardItems?.first)
        #expect(restored.types.map(\.rawValue).filter { $0 != restoreTokenPasteboardType.rawValue }
            == [NSPasteboard.PasteboardType.png.rawValue, NSPasteboard.PasteboardType.html.rawValue])
        #expect(!restored.types.contains(.string))
    }

    @Test func imageWithOnlyAURLDoesNotGainPlainText() async throws {
        let fixture = try PrivacyFixture()
        defer { fixture.close() }
        let source = NSPasteboardItem()
        source.setData(try privacyPNG(), forType: .png)
        source.setString("https://example.com/cat.png", forType: .URL)
        fixture.write([source])
        fixture.store.pollPasteboard()
        await fixture.store.waitForPendingImageCapture()
        let item = try #require(fixture.store.items.first)

        #expect(fixture.store.copy(item))

        let restored = try #require(fixture.pasteboard.pasteboardItems?.first)
        #expect(!restored.types.contains(.string))
        #expect(restored.string(forType: .URL) == "https://example.com/cat.png")
        #expect(restored.types.first == .png)
    }

    @Test func restoredFormatsKeepTheSourceOrder() throws {
        let fixture = try PrivacyFixture()
        defer { fixture.close() }
        let rtf = try #require(NSAttributedString(string: "Ordered").rtf(
            from: NSRange(location: 0, length: 7),
            documentAttributes: [:]
        ))
        let source = NSPasteboardItem()
        source.setData(rtf, forType: .rtf)
        source.setString("<b>Ordered</b>", forType: .html)
        source.setString("Ordered", forType: .string)
        fixture.write([source])
        // The pasteboard server groups its own conversions (for example UTF-16
        // text derived from RTF), so compare against what AppKit reports.
        let sourceTypes = try #require(fixture.pasteboard.pasteboardItems?.first?.types)
        fixture.store.pollPasteboard()
        let item = try #require(fixture.store.items.first)

        fixture.write([privacyText("something else")])
        #expect(fixture.store.copy(item))

        let restored = try #require(fixture.pasteboard.pasteboardItems?.first)
        #expect(restored.types.filter { $0 != restoreTokenPasteboardType } == sourceTypes)
        #expect(sourceTypes.firstIndex(of: .rtf) ?? 0 < sourceTypes.firstIndex(of: .html) ?? 0)
    }

    @Test func htmlOnlyTextGainsPlainTextAfterItsOriginalFormats() throws {
        let fixture = try PrivacyFixture()
        defer { fixture.close() }
        let source = NSPasteboardItem()
        source.setString("<p>Only <i>HTML</i></p>", forType: .html)
        fixture.write([source])
        fixture.store.pollPasteboard()
        let item = try #require(fixture.store.items.first)
        #expect(item.text == "Only HTML\n")

        #expect(fixture.store.copy(item))

        let restored = try #require(fixture.pasteboard.pasteboardItems?.first)
        #expect(restored.types.filter { $0 != restoreTokenPasteboardType } == [.html, .string])
        #expect(restored.string(forType: .string) == "Only HTML\n")
    }
}

@MainActor
private struct PrivacyFixture {
    let pasteboard: NSPasteboard
    let defaults: UserDefaults
    let suite: String
    let store: ClipboardStore

    init(frontmost: String? = nil, configuration: ClipboardStore.Configuration = .default) throws {
        suite = "ClipDeckPrivacyTests.\(UUID().uuidString)"
        defaults = try #require(UserDefaults(suiteName: suite))
        defaults.set(true, forKey: "monitoring")
        pasteboard = NSPasteboard(name: .init(suite))
        store = ClipboardStore(
            pasteboard: pasteboard,
            startsMonitoring: false,
            performsLegacyCleanup: false,
            userDefaults: defaults,
            monitoringDefaultsKey: "monitoring",
            configuration: configuration,
            frontmostApplicationIdentifier: { frontmost }
        )
    }

    func write(_ objects: [NSPasteboardWriting]) {
        pasteboard.clearContents()
        #expect(pasteboard.writeObjects(objects))
    }

    func close() {
        defaults.removePersistentDomain(forName: suite)
        pasteboard.releaseGlobally()
    }
}

@MainActor private func privacyText(_ value: String) -> NSPasteboardItem {
    let item = NSPasteboardItem()
    item.setString(value, forType: .string)
    return item
}

@MainActor private func privacyPNG() throws -> Data {
    let bitmap = try #require(NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: 12, pixelsHigh: 8,
        bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true, isPlanar: false, colorSpaceName: .deviceRGB,
        bytesPerRow: 48, bitsPerPixel: 32))
    return try #require(bitmap.representation(using: .png, properties: [:]))
}

private final class CountingStringProvider: NSObject, NSPasteboardItemDataProvider, @unchecked Sendable {
    private let lock = NSLock()
    private var reads = 0
    private let value: String

    init(value: String) {
        self.value = value
    }

    var readCount: Int { lock.withLock { reads } }

    func pasteboard(_ pasteboard: NSPasteboard?, item: NSPasteboardItem, provideDataForType type: NSPasteboard.PasteboardType) {
        lock.withLock { reads += 1 }
        item.setString(value, forType: type)
    }
}
